"""More scam families (data only) for scams_db.py: affinity fraud, network-marketing traps, utility-bill and token scams, school-fees fraud, 'paid task' scams,
fake payment proof, pump-and-dump groups, overseas-job traps and counterfeit goods. Same format as scams_data.py: key: (aliases, en, fr, rw, sw), each (name, what it is, example, how to protect yourself).
Protective only; examples are invented. fr/rw/sw wording is a draft for fluent review."""

EXTRA4 = {
"affinity": (["affinity fraud", "religious scam", "church scam", "community investment scam", "group trust scam", "fraude par affinite"],
  ("Affinity fraud", "A scammer uses trust inside a group (church, community, family, alumni, cooperative or WhatsApp group) to sell a fake investment or request money, because members trust each other and do not check.", "A respected member promises 'guaranteed blessings' of 40% a month from a community fund and asks everyone to pay through him.", "Check any investment with the regulator and in writing, no matter who recommends it; guaranteed high returns are a warning; never be pressured by the group; ask for audited accounts; do not recruit friends."),
  ("Fraude par affinité", "Un escroc exploite la confiance au sein d'un groupe (église, communauté, famille, anciens élèves, coopérative ou groupe WhatsApp) pour vendre un faux placement ou demander de l'argent, car les membres se font confiance et ne vérifient pas.", "Un membre respecté promet « 40 % par mois garantis » grâce à un fonds communautaire et demande à tous de payer par lui.", "Vérifiez tout placement auprès du régulateur et par écrit, quel que soit le recommandeur ; des rendements élevés garantis sont un signal d'alerte ; ne cédez pas à la pression du groupe ; demandez des comptes audités ; ne recrutez pas vos amis."),
  ("Uburiganya bukoresha icyizere mu itsinda", "Umutekamutwe akoresha icyizere kiri mu itsinda (itorero, umuryango, abarangije hamwe, koperative cyangwa WhatsApp group) kugira ngo agurishe ishoramari ry'impimbano cyangwa asabe amafaranga, kuko abanyamuryango bizerana ntibagenzure.", "Umunyamuryango wubashywe asezeranya «inyungu ya 40% buri kwezi ikizewe» mu kigega cy'umuryango agasaba bose kwishyura binyuze kuri we.", "Genzura ishoramari ryose ku buyobozi bubishinzwe no mu nyandiko, uwo ari we wese ubigusabye; inyungu nyinshi zemejwe ni ikimenyetso cy'impuruza; ntukemere gukandwa n'itsinda; saba imibare yagenzuwe; ntukurure inshuti."),
  ("Ulaghai wa kutumia uaminifu wa kikundi", "Tapeli hutumia uaminifu ndani ya kikundi (kanisa, jamii, familia, wahitimu, ushirika au kikundi cha WhatsApp) kuuza uwekezaji bandia au kuomba pesa, kwa sababu wanachama huaminiana na hawakagui.", "Mwanachama anayeheshimiwa anaahidi 'baraka za uhakika' za 40% kwa mwezi kutoka mfuko wa jamii na kuomba wote walipe kupitia kwake.", "Hakiki uwekezaji wowote na mdhibiti na kwa maandishi, bila kujali anayependekeza; faida kubwa za uhakika ni ishara ya hatari; usishinikizwe na kikundi; omba hesabu zilizokaguliwa; usiwaajiri marafiki.")),
"mlm": (["multi level marketing scam", "mlm scam", "network marketing scam", "business opportunity scam", "recruitment scheme", "get rich recruiting", "marketing de reseau arnaque"],
  ("Network-marketing and 'business opportunity' traps", "A scheme where you pay to join and earn mainly by recruiting others and buying stock, not by selling real products to real customers. Most members lose money while the top few profit.", "A 'training' costs 150,000 RWF to join and promises riches if you bring five friends and buy a starter pack.", "Ask how much comes from real retail sales versus recruitment; never pay to join or buy stock you cannot resell; read the income disclosure; be careful with lifestyle photos and pressure; check the company with the authorities."),
  ("Pièges du marketing de réseau et des « opportunités d'affaires »", "Un système où l'on paie pour adhérer et où l'on gagne surtout en recrutant d'autres personnes et en achetant du stock, pas en vendant de vrais produits à de vrais clients. La plupart des membres perdent de l'argent tandis que quelques-uns au sommet gagnent.", "Une « formation » coûte 150 000 RWF à l'adhésion et promet la richesse si vous amenez cinq amis et achetez un pack de départ.", "Demandez quelle part vient des ventes réelles et du recrutement ; ne payez jamais pour adhérer ni n'achetez du stock invendable ; lisez la déclaration de revenus ; méfiez-vous des photos de luxe et de la pression ; vérifiez l'entreprise auprès des autorités."),
  ("Imitego y'ubucuruzi bwo kwiyandikisha n'«amahirwe y'ubucuruzi»", "Gahunda aho wishyura kugira ngo winjire ukunguka cyane ukurura abandi no kugura ibicuruzwa, aho kugurisha ibintu nyakuri ku bakiriya nyakuri. Abenshi batakaza amafaranga mu gihe bake bo hejuru ari bo bunguka.", "«Amahugurwa» yishyurwa 150,000 RWF yo kwinjira asezeranya ubukire nutwara inshuti eshanu ukagura ipaki y'itangiriro.", "Baza amafaranga aturuka ku igurisha nyakuri ugereranyije no gukurura abantu; ntukishyure kwinjira cyangwa kugura ibicuruzwa utagurisha; soma inyandiko y'inyungu; witondere amafoto y'ubuzima buhenze no gukandwa; genzura ikigo ku buyobozi."),
  ("Mitego ya biashara ya mtandao na 'fursa za biashara'", "Mpango ambapo unalipa kujiunga na kupata zaidi kwa kuwaajiri wengine na kununua bidhaa, si kwa kuuza bidhaa halisi kwa wateja halisi. Wanachama wengi hupoteza pesa huku wachache wa juu wakipata faida.", "'Mafunzo' yanagharimu RWF 150,000 kujiunga na kuahidi utajiri ukileta marafiki watano na kununua kifurushi cha kuanzia.", "Uliza ni kiasi gani kinatokana na mauzo halisi dhidi ya kuajiri; kamwe usilipe kujiunga au kununua bidhaa usizoweza kuuza; soma tamko la mapato; kuwa makini na picha za maisha ya anasa na shinikizo; hakiki kampuni kwa mamlaka.")),
"utilitybill": (["electricity token scam", "cash power scam", "utility bill scam", "water bill scam", "fake electricity", "electricity bill scam", "fraude facture electricite", "tax refund scam", "fake tax notice"],
  ("Utility bill, electricity-token and tax-notice scams", "Fake messages or callers claim your electricity, water or tax account has a debt, that your power will be cut, or that you are owed a refund, and tell you to pay or 'verify' through a number or link they give you.", "An SMS says 'Your electricity will be disconnected today, pay arrears to this number' with a mobile-money number of a private person.", "Pay bills only through the official app, USSD code or office you already use; utilities do not ask you to send money to a personal number; check the account in your own app; do not click links; report the message to the provider."),
  ("Arnaques aux factures (électricité, eau) et aux avis d'impôts", "De faux messages ou appelants prétendent que votre compte d'électricité, d'eau ou d'impôts a une dette, que le courant va être coupé ou qu'un remboursement vous est dû, et vous demandent de payer ou de « vérifier » via un numéro ou lien qu'ils fournissent.", "Un SMS dit « Votre électricité sera coupée aujourd'hui, payez l'arriéré à ce numéro » avec le numéro mobile money d'un particulier.", "Payez vos factures uniquement par l'application, le code USSD ou le guichet officiel que vous utilisez déjà ; un fournisseur ne demande pas d'envoyer de l'argent à un numéro personnel ; vérifiez le compte dans votre propre application ; ne cliquez pas ; signalez le message au fournisseur."),
  ("Uburiganya ku mafaranga y'amashanyarazi, amazi n'imisoro", "Ubutumwa bw'impimbano cyangwa uhamagaye bavuga ko konti yawe y'amashanyarazi, amazi cyangwa imisoro ifite umwenda, ko umuriro uzakurwaho, cyangwa ko ugomba gusubizwa amafaranga, bakagusaba kwishyura cyangwa «kugenzura» unyuze kuri nimero cyangwa link batanze.", "SMS ivuga ngo «Umuriro wawe uzakurwaho uyu munsi, ishyura ibirarane kuri iyi nimero» ifite nimero ya mobile money y'umuntu ku giti cye.", "Ishyura fagitire unyuze gusa kuri porogaramu, kode ya USSD cyangwa ibiro byemewe usanzwe ukoresha; ikigo ntigisaba kohereza amafaranga kuri nimero y'umuntu; reba konti muri porogaramu yawe; ntukande link; menyesha ubutumwa ku kigo."),
  ("Ulaghai wa bili za umeme, maji na notisi za kodi", "Ujumbe au wapigaji bandia wanadai akaunti yako ya umeme, maji au kodi ina deni, kwamba umeme utakatwa, au unadaiwa marejesho, na kukuambia ulipe au 'uthibitishe' kupitia namba au kiungo wanachotoa.", "SMS inasema 'Umeme wako utakatwa leo, lipa malimbikizo kwa namba hii' ikiwa na namba ya pesa za simu ya mtu binafsi.", "Lipa bili kupitia programu, msimbo wa USSD au ofisi rasmi unayoitumia tayari; huduma haziombi utume pesa kwa namba binafsi; kagua akaunti kwenye programu yako; usibofye viungo; ripoti ujumbe kwa mtoa huduma.")),
"schoolfees": (["school fees scam", "tuition scam", "fake school fees", "fee payment scam", "fake university admission", "admission scam", "fraude frais de scolarite"],
  ("School-fees and fake-admission scams", "Criminals send a 'new bank account' for school fees, pretend to be a school or university office, or sell fake admissions and scholarships, so parents and students pay money that never reaches the school.", "A WhatsApp message from 'the bursar' says the fees account has changed and asks parents to pay to a new mobile-money number before Friday.", "Confirm any change of account in person or by calling the school's known number; pay only into accounts on official fee notices; never pay for admission or scholarship 'processing' to personal numbers; check the institution and programme on official lists."),
  ("Arnaques aux frais de scolarité et aux fausses admissions", "Des criminels envoient un « nouveau compte bancaire » pour les frais, se font passer pour le bureau d'une école ou université, ou vendent de fausses admissions et bourses ; parents et étudiants paient de l'argent qui n'arrive jamais à l'école.", "Un message WhatsApp du « comptable » dit que le compte des frais a changé et demande aux parents de payer à un nouveau numéro mobile money avant vendredi.", "Confirmez tout changement de compte en personne ou en appelant le numéro connu de l'école ; ne payez que sur les comptes figurant sur les avis officiels ; ne payez jamais l'« étude du dossier » d'admission ou de bourse sur un numéro personnel ; vérifiez l'établissement et la filière sur les listes officielles."),
  ("Uburiganya ku mafaranga y'ishuri no kwinjira mu mashuri b'impimbano", "Abagizi ba nabi bohereza «konti nshya ya banki» y'amafaranga y'ishuri, biyitirira ibiro by'ishuri cyangwa kaminuza, cyangwa bagurisha amanota yo kwinjira na bourse by'impimbano, ababyeyi n'abanyeshuri bakishyura amafaranga atagera ku ishuri.", "Ubutumwa bwa WhatsApp buturutse kuri «umucungamari» buvuga ko konti y'amafaranga y'ishuri yahindutse busaba ababyeyi kwishyura kuri nimero nshya ya mobile money mbere y'ku wa gatanu.", "Emeza ihinduka ryose rya konti imbonankubone cyangwa uhamagare nimero y'ishuri izwi; ishyura gusa kuri konti ziri ku mabaruwa yemewe; ntukishyure «gutunganya dosiye» yo kwinjira cyangwa bourse kuri nimero y'umuntu; genzura ikigo n'ishami ku rutonde rwemewe."),
  ("Ulaghai wa ada za shule na udahili bandia", "Wahalifu hutuma 'akaunti mpya ya benki' ya ada, hujifanya ofisi ya shule au chuo kikuu, au huuza udahili na ufadhili bandia, wazazi na wanafunzi wakilipa pesa zisizofika shuleni.", "Ujumbe wa WhatsApp kutoka 'mhasibu' unasema akaunti ya ada imebadilika na kuwaomba wazazi walipe kwa namba mpya ya pesa za simu kabla ya Ijumaa.", "Thibitisha mabadiliko yoyote ya akaunti ana kwa ana au kwa kupiga namba inayojulikana ya shule; lipa tu kwenye akaunti zilizo kwenye notisi rasmi za ada; kamwe usilipe 'uchakataji' wa udahili au ufadhili kwa namba binafsi; hakiki taasisi na programu kwenye orodha rasmi.")),
"taskscam": (["task scam", "like and earn", "like and earn scam", "like and earn scams", "paid tasks scam", "online task scam", "like videos earn money", "work from home task scam", "click and earn", "fake commission tasks", "arnaque taches en ligne"],
  ("'Paid task' and 'like and earn' scams", "You are offered easy money for simple online tasks (liking videos, rating products, boosting orders). The first small tasks are paid to win trust, then you are asked to 'deposit' money to unlock bigger tasks or withdrawals, and the money is never returned.", "A message offers 5,000 RWF a day to like videos; after two small payouts a 'manager' says you must deposit 100,000 RWF to continue and withdraw.", "Real work never asks you to pay to earn; stop at the first request for a deposit; do not join Telegram or WhatsApp 'task groups'; do not give ID or bank details; report the number and block it."),
  ("Arnaques aux « tâches payées » et « likez et gagnez »", "On vous propose de l'argent facile pour de petites tâches en ligne (aimer des vidéos, noter des produits, booster des commandes). Les premières petites tâches sont payées pour gagner votre confiance, puis on vous demande de « déposer » de l'argent pour débloquer de plus grosses tâches ou retraits, et l'argent n'est jamais rendu.", "Un message offre 5 000 RWF par jour pour aimer des vidéos ; après deux petits paiements, un « manager » dit qu'il faut déposer 100 000 RWF pour continuer et retirer.", "Un vrai travail ne demande jamais de payer pour gagner ; arrêtez à la première demande de dépôt ; ne rejoignez pas de « groupes de tâches » Telegram ou WhatsApp ; ne donnez ni pièce d'identité ni coordonnées bancaires ; signalez et bloquez le numéro."),
  ("Uburiganya bwa «imirimo yishyurwa» na «kanda like ubone amafaranga»", "Baguha amafaranga yoroshye ku mirimo yoroheje yo kuri interineti (gukunda amashusho, gutanga amanota ku bicuruzwa). Imirimo mike ya mbere iriahwa kugira ngo bakwizerwe, hanyuma bakagusaba «gushyira» amafaranga kugira ngo ufungure imirimo minini cyangwa kubikuza, kandi amafaranga ntagaruka.", "Ubutumwa buguha 5,000 RWF ku munsi wo gukunda amashusho; nyuma y'ubwishyu bubiri buto «umuyobozi» avuga ko ugomba gushyiramo 100,000 RWF kugira ngo ukomeze ubikuze.", "Akazi nyako ntigasaba kwishyura kugira ngo ubone amafaranga; hagarara ku busabe bwa mbere bwo gushyiramo amafaranga; ntukinjire mu matsinda ya Telegram cyangwa WhatsApp y'«imirimo»; ntugire indangamuntu cyangwa amakuru ya banki; menyesha kandi uhagarike nimero."),
  ("Ulaghai wa 'kazi za kulipwa' na 'bofya like upate pesa'", "Unapewa pesa rahisi kwa kazi rahisi za mtandaoni (kupenda video, kukadiria bidhaa, kuongeza oda). Kazi ndogo za kwanza hulipwa kupata imani, kisha unaombwa 'kuweka' pesa ili kufungua kazi kubwa au kutoa, na pesa hairudishwi.", "Ujumbe unatoa RWF 5,000 kwa siku kwa kupenda video; baada ya malipo mawili madogo 'meneja' anasema lazima uweke RWF 100,000 ili kuendelea na kutoa.", "Kazi halisi haikuombi ulipe ili upate; simama kwenye ombi la kwanza la amana; usijiunge na 'vikundi vya kazi' vya Telegram au WhatsApp; usitoe kitambulisho au taarifa za benki; ripoti na uzuie namba.")),
"paymentproof": (["fake payment screenshot", "fake payment proof", "payment screenshot scam", "fake mobile money confirmation", "fake transfer receipt", "fake payment sms", "fake bank slip", "faux justificatif de paiement"],
  ("Fake payment screenshot and fake confirmation scams", "A 'buyer' shows an edited screenshot, receipt or SMS saying they paid, so the seller hands over goods or change; the money never arrived. Another version sends a fake 'payment received, refund the extra' message.", "A buyer shows a mobile-money confirmation and asks you to hand over the phone and return 20,000 RWF 'sent by mistake', but your balance did not change.", "Never release goods or give change until the money appears in YOUR account or wallet balance; do not trust screenshots, receipts or SMS shown to you; check the transaction history in your own app; be careful with rushed 'refund the extra' requests."),
  ("Arnaques aux fausses captures de paiement et fausses confirmations", "Un « acheteur » montre une capture, un reçu ou un SMS modifié disant qu'il a payé, et le vendeur remet la marchandise ou la monnaie ; l'argent n'est jamais arrivé. Variante : un faux message « paiement reçu, remboursez le trop-perçu ».", "Un acheteur montre une confirmation mobile money et demande de livrer le téléphone et de rendre 20 000 RWF « envoyés par erreur », mais votre solde n'a pas bougé.", "Ne remettez jamais la marchandise ni la monnaie avant que l'argent apparaisse sur VOTRE solde ; ne vous fiez pas aux captures, reçus ou SMS montrés ; vérifiez l'historique dans votre propre application ; méfiez-vous des demandes pressées de « rembourser le trop-perçu »."),
  ("Uburiganya bwa screenshot y'ubwishyu bw'impimbano na confirmation z'impimbano", "«Umuguzi» agaragaza screenshot, inyemezabwishyu cyangwa SMS yahinduwe ivuga ko yishyuye, umucuruzi agatanga ibicuruzwa cyangwa ibiceri; amafaranga ntarigeze agera. Ubundi buryo: ubutumwa bw'impimbano «amafaranga yageze, subiza arenga».", "Umuguzi agaragaza confirmation ya mobile money agasaba guhabwa telefone no gusubizwa 20,000 RWF «yoherejwe kubw'impanuka», ariko konti yawe ntiyahindutse.", "Ntuzigere utanga ibicuruzwa cyangwa ibiceri kugeza amafaranga agaragaye ku mubare wa KONTI YAWE; ntukizere screenshots, inyemezabwishyu cyangwa SMS werekwa; reba amateka y'ibikorwa muri porogaramu yawe; witondere ubusabe bwihuta bwo «gusubiza arenga»."),
  ("Ulaghai wa picha ya malipo bandia na uthibitisho bandia", "'Mnunuzi' anaonyesha picha ya skrini, risiti au SMS iliyohaririwa inayosema amelipa, muuzaji akakabidhi bidhaa au chenji; pesa haijafika kamwe. Toleo jingine: ujumbe bandia 'malipo yamepokelewa, rudisha ziada'.", "Mnunuzi anaonyesha uthibitisho wa pesa za simu na kuomba umkabidhi simu na kurudisha RWF 20,000 'zilizotumwa kwa makosa', lakini salio lako halikubadilika.", "Kamwe usikabidhi bidhaa au chenji hadi pesa ionekane kwenye salio la AKAUNTI YAKO; usiamini picha za skrini, risiti au SMS ulizoonyeshwa; kagua historia ya miamala kwenye programu yako; kuwa makini na maombi ya haraka ya 'rudisha ziada'.")),
"pumpdump": (["pump and dump", "crypto pump group", "telegram signals scam", "whatsapp investment group", "trading signals scam", "investment group scam", "fake trading group", "groupe signaux arnaque"],
  ("Pump-and-dump and fake 'trading signal' groups", "Chat groups on Telegram or WhatsApp urge members to buy a coin or share at the same time so insiders can sell high, or sell paid 'signals' and 'guaranteed profit' accounts managed by someone else. Latecomers lose.", "An admin announces 'the next coin will triple in one hour, buy now' and posts screenshots of fake profits.", "Do not trade on tips from groups or strangers; guaranteed profits do not exist; never give someone control of your trading or wallet; check whether the platform and adviser are licensed; invest only money you can afford to lose."),
  ("Groupes « pump and dump » et faux « signaux de trading »", "Des groupes de discussion Telegram ou WhatsApp poussent à acheter en même temps une cryptomonnaie ou une action pour que les initiés revendent plus cher, ou vendent des « signaux » payants et des comptes à « profit garanti » gérés par un tiers. Les derniers arrivés perdent.", "Un admin annonce « la prochaine pièce va tripler en une heure, achetez maintenant » et publie de fausses captures de profits.", "Ne tradez pas sur les conseils de groupes ou d'inconnus ; les profits garantis n'existent pas ; ne donnez jamais à quelqu'un le contrôle de votre compte de trading ou portefeuille ; vérifiez que la plateforme et le conseiller sont agréés ; n'investissez que ce que vous pouvez perdre."),
  ("Amatsinda ya «pump and dump» na «signals» z'ubucuruzi z'impimbano", "Amatsinda ya Telegram cyangwa WhatsApp ashishikariza abanyamuryango kugura coin cyangwa imigabane icyarimwe kugira ngo abafite amakuru y'imbere bagurishe ku giciro kiri hejuru, cyangwa agurisha «signals» zishyurwa na konti z'«inyungu yemejwe» zicungwa n'undi muntu. Abaje nyuma batakaza.", "Umuyobozi atangaza ati «coin itaha izikuba gatatu mu isaha imwe, gura ubu» agashyiraho screenshots z'inyungu z'impimbano.", "Ntucuruze ku nama z'amatsinda cyangwa z'abantu utazi; inyungu zemejwe ntizibaho; ntuzigere uha undi kugenzura konti yawe y'ubucuruzi cyangwa wallet; genzura ko urubuga n'umujyanama bafite uruhushya; shora gusa amafaranga ushobora gutakaza."),
  ("Makundi ya 'pump and dump' na 'ishara za biashara' bandia", "Makundi ya mazungumzo ya Telegram au WhatsApp huhimiza wanachama kununua sarafu au hisa kwa wakati mmoja ili wa ndani wauze juu, au kuuza 'ishara' za kulipia na akaunti za 'faida ya uhakika' zinazosimamiwa na mtu mwingine. Waliochelewa hupoteza.", "Msimamizi anatangaza 'sarafu inayofuata itakuwa mara tatu ndani ya saa moja, nunua sasa' na kuchapisha picha za skrini za faida bandia.", "Usifanye biashara kwa vidokezo vya makundi au wageni; faida za uhakika hazipo; kamwe usimpe mtu udhibiti wa akaunti yako ya biashara au pochi; hakiki kama jukwaa na mshauri wana leseni; wekeza pesa unazoweza kupoteza tu.")),
"traffickingjob": (["overseas job trafficking", "fake job abroad trafficking", "human trafficking job offer", "job abroad passport scam", "domestic work abroad scam", "recruitment agency scam abroad", "offre emploi etranger traite"],
  ("Overseas job offers that lead to trafficking or forced labour", "Attractive offers of well-paid work abroad (domestic work, hotels, security, modelling, call centres) from unregistered agents who take fees, keep your passport, and may send you into forced labour, debt bondage or exploitation.", "An agent offers a 1,200-dollar job in a hotel abroad, asks for a fee and your passport 'to process', and gives vague details about the employer.", "Use only licensed recruitment agencies and check them with the labour ministry or migration authority; get a written contract in a language you understand; never hand over your passport; tell family the address and employer; contact the authorities or a trusted organisation if something seems wrong."),
  ("Offres d'emploi à l'étranger menant à la traite ou au travail forcé", "Offres alléchantes de travail bien payé à l'étranger (travail domestique, hôtels, sécurité, mannequinat, centres d'appels) par des agents non enregistrés qui prennent des frais, gardent votre passeport et peuvent vous envoyer vers le travail forcé, la servitude pour dettes ou l'exploitation.", "Un agent propose un emploi d'hôtel à 1 200 dollars à l'étranger, demande des frais et votre passeport « pour traitement » et donne peu de détails sur l'employeur.", "N'utilisez que des agences agréées et vérifiez-les auprès du ministère du travail ou de l'autorité des migrations ; exigez un contrat écrit dans une langue que vous comprenez ; ne remettez jamais votre passeport ; donnez à votre famille l'adresse et l'employeur ; contactez les autorités ou une organisation de confiance si quelque chose semble anormal."),
  ("Amatangazo y'akazi hanze y'igihugu atera gucuruzwa kw'abantu cyangwa gukoreshwa ku ngufu", "Amatangazo ashishikaje y'akazi gahembwa neza hanze (akazi ko mu rugo, amahoteli, umutekano, kwerekana imideli, call centres) aturutse ku bakozi batanditswe bafata amafaranga, bakagumana pasiporo yawe kandi bashobora kukujyana mu gukoreshwa ku ngufu, imyenda cyangwa ihohoterwa.", "Umukozi atanga akazi ka hoteli k'amadolari 1,200 hanze, agasaba amafaranga na pasiporo yawe «kugira ngo bayitunganye», agatanga amakuru make ku mukoresha.", "Koresha gusa ibigo bifite uruhushya kandi ubigenzure ku ministeri y'umurimo cyangwa ubuyobozi bw'abimukira; saba amasezerano yanditse mu rurimi usobanukiwe; ntuzigere utanga pasiporo yawe; menyesha umuryango aho uri n'umukoresha; vugana n'ubuyobozi cyangwa umuryango wizewe niba hari ikitagenda neza."),
  ("Ofa za kazi nje ya nchi zinazoongoza kwa biashara ya binadamu au kazi ya kulazimishwa", "Ofa za kuvutia za kazi yenye malipo mazuri nje (kazi za nyumbani, hoteli, ulinzi, uanamitindo, vituo vya simu) kutoka kwa mawakala wasiosajiliwa wanaochukua ada, kushikilia pasipoti yako, na wanaweza kukupeleka kwenye kazi ya kulazimishwa, utumwa wa deni au unyonyaji.", "Wakala anatoa kazi ya hoteli ya dola 1,200 nje, anaomba ada na pasipoti yako 'kuchakata', na kutoa maelezo hafifu kuhusu mwajiri.", "Tumia mawakala wenye leseni tu na uwahakiki na wizara ya kazi au mamlaka ya uhamiaji; pata mkataba wa maandishi kwa lugha unayoielewa; kamwe usikabidhi pasipoti yako; mwambie familia anwani na mwajiri; wasiliana na mamlaka au shirika linaloaminika kama kuna kitu hakiko sawa.")),
"counterfeit": (["counterfeit goods", "fake products scam", "fake medicine scam", "counterfeit medicine", "fake branded goods", "fake phones scam", "fake electronics", "fake cosmetics", "contrefacon arnaque", "fake spare parts"],
  ("Counterfeit goods and fake medicines sold online", "Online sellers advertise branded phones, cosmetics, spare parts or medicines at very low prices; the goods are fake, unsafe or never delivered. Fake medicines can be dangerous or useless.", "A social-media shop sells 'original' smartphones at half the price, asks full payment first and sends a cheap copy or nothing.", "Buy from known shops or official stores; be careful with prices far below the market; pay on delivery or check before paying; buy medicines only from licensed pharmacies and check packaging and registration; keep proof and report the seller."),
  ("Produits contrefaits et faux médicaments vendus en ligne", "Des vendeurs en ligne proposent téléphones, cosmétiques, pièces ou médicaments de marque à très bas prix ; les produits sont faux, dangereux ou jamais livrés. Les faux médicaments peuvent être dangereux ou inutiles.", "Une boutique sur les réseaux sociaux vend des smartphones « originaux » à moitié prix, exige le paiement intégral d'abord et envoie une copie bon marché ou rien.", "Achetez dans des boutiques connues ou officielles ; méfiez-vous des prix très inférieurs au marché ; payez à la livraison ou vérifiez avant de payer ; n'achetez des médicaments que dans des pharmacies agréées et vérifiez emballage et enregistrement ; gardez les preuves et signalez le vendeur."),
  ("Ibicuruzwa by'impimbano n'imiti y'impimbano bigurishwa kuri interineti", "Abacuruzi bo kuri interineti bamamaza telefone, ibirungo, ibice by'imodoka cyangwa imiti y'ikirango ku giciro gito cyane; ibicuruzwa ni iby'impimbano, biteje akaga cyangwa ntibitangwa. Imiti y'impimbano ishobora guteza akaga cyangwa ntikore.", "Iduka ryo ku mbuga nkoranyambaga rigurisha telefone «umwimerere» ku giciro cya kimwe cya kabiri, risaba kwishyura byose mbere rigatanga kopi ihendutse cyangwa ntiritange.", "Gura mu maduka azwi cyangwa yemewe; witondere ibiciro biri hasi cyane y'isoko; ishyura igihe bigeze cyangwa ugenzure mbere yo kwishyura; gura imiti gusa muri farumasi zifite uruhushya ugenzure ipaki n'iyandikwa; bika ibimenyetso kandi umenyeshe umucuruzi."),
  ("Bidhaa bandia na dawa bandia zinazouzwa mtandaoni", "Wauzaji wa mtandaoni hutangaza simu, vipodozi, vipuri au dawa za chapa kwa bei ndogo sana; bidhaa ni bandia, si salama au hazifiki kamwe. Dawa bandia zinaweza kuwa hatari au zisizo na kazi.", "Duka la mitandao ya kijamii linauza simu 'asili' kwa nusu bei, linaomba malipo kamili kwanza na kutuma nakala ya bei nafuu au hakuna.", "Nunua kutoka maduka yanayojulikana au rasmi; kuwa makini na bei chini sana ya soko; lipa wakati wa kupokea au kagua kabla ya kulipa; nunua dawa kutoka maduka ya dawa yenye leseni tu na kagua vifungashio na usajili; hifadhi ushahidi na ripoti muuzaji.")),
}
